    #[test]
    fn open_session_records_declared_context_and_omits_it_when_undeclared() {
        let engine = Lodestar::open_in_memory().expect("in-memory engine");
        let sessions = SessionRegistry::new("copilot").unwrap();
        const TOKEN: &str = "00112233445566778899aabbccddeeff";
        let body = |arguments: Value| -> Value {
            let params = json!({ "name": "open_session", "arguments": arguments });
            let bound = bind_session(&params, &sessions).expect("session binds");
            let result = call(&engine, &bound).expect("open_session succeeds");
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap())
                .expect("body is JSON")
        };

        let undeclared = body(json!({ "session_id": TOKEN }));
        assert!(undeclared["agent_id"].is_string());
        assert!(undeclared.get("context").is_none());

        let declared = body(json!({
            "session_id": TOKEN,
            "branch": "fleet/typed-controls",
            "dirty": false,
        }));
        assert_eq!(declared["agent_id"], undeclared["agent_id"]);
        assert_eq!(declared["context"]["branch"], "fleet/typed-controls");
        assert_eq!(declared["context"]["dirty"], false);
        assert!(declared["context"].get("head_sha").is_none());
        assert_eq!(
            sessions.resolve(TOKEN).unwrap().context.branch.unwrap(),
            "fleet/typed-controls"
        );

        // Reconnecting is the first call an owner is guaranteed to make. A
        // paused task that only exists on the board still depends on memory,
        // which this repository has repeatedly measured at zero adoption.
        let agent = undeclared["agent_id"].as_str().unwrap();
        let goal = engine
            .define_goal(lodestar_core::GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let paused = engine.create_task(&goal.id, "Paused work", "done").unwrap();
        assert!(engine.claim_task(&paused.id, agent, 600).unwrap());
        assert!(engine
            .pause_task(&paused.id, agent, Some("waiting for the server restart"))
            .unwrap());

        let reconnected = body(json!({ "session_id": TOKEN }));
        assert_eq!(reconnected["paused_by_you"][0]["task_id"], paused.id);
        assert_eq!(
            reconnected["paused_by_you"][0]["reason"],
            "waiting for the server restart"
        );
        assert!(reconnected["paused_advice"]
            .as_str()
            .unwrap()
            .contains("task_transition with to=\"resume\""));

        let other = body(json!({
            "session_id": "ffeeddccbbaa99887766554433221100"
        }));
        assert!(other.get("paused_by_you").is_none());
    }

    // Regression (ADR-0044): the durable row survives a bare re-registration.
    //
    // `canonical-push` re-opens the session on every publish just to learn its
    // own agent id, declaring nothing. That used to overwrite the stored row
    // with an empty one, so `fleet_view` reported `branch: null` for agents that
    // had declared a branch minutes earlier — the fleet went blind at exactly
    // the moment it was busiest, and the tool that blinded it was the one added
    // to record where everyone was working.
    #[test]
    fn a_bare_re_registration_does_not_erase_the_durable_context() {
        let engine = Lodestar::open_in_memory().expect("in-memory engine");
        let sessions = SessionRegistry::new("copilot").unwrap();
        const TOKEN: &str = "aabbccddeeff00112233445566778899";
        let open = |arguments: Value| {
            let params = json!({ "name": "open_session", "arguments": arguments });
            let bound = bind_session(&params, &sessions).expect("session binds");
            call(&engine, &bound).expect("open_session succeeds");
        };

        open(json!({ "session_id": TOKEN, "branch": "fleet/claim-gate", "behind": 0 }));
        let agent_id = sessions.resolve(TOKEN).unwrap().agent_id;
        assert_eq!(
            engine.fleet_view().unwrap().sessions[0].context.branch,
            Some("fleet/claim-gate".to_string())
        );

        // The publish path: identity only, nothing declared.
        open(json!({ "session_id": TOKEN }));

        let view = engine.fleet_view().unwrap();
        let session = view
            .sessions
            .iter()
            .find(|session| session.agent_id == agent_id)
            .expect("the session is still in the view");
        assert_eq!(session.context.branch, Some("fleet/claim-gate".to_string()));
        assert_eq!(session.context.behind, Some(0));
    }

    /// Every tool the server will answer to is a tool it advertises.
    ///
    /// `active_knowledge` dispatched for months and appeared in no
    /// `definitions()` list, so the only way to discover that the repository's
    /// learned knowledge could be read at all was to read the Rust. From the
    /// tool surface the knowledge base looked write-only: record, promote,
    /// reconfirm, prune, and no way to see what was already known — which is
    /// exactly the state that makes an agent rediscover, expensively, what
    /// somebody already wrote down.
    ///
    /// This is the mirror of the undeclared-argument bug above. There the
    /// contract asked for something it never mentioned; here the server answers
    /// to something it never mentions. Both fail the same way: the code is
    /// right, the advertisement is wrong, and nothing breaks loudly enough to
    /// be found.
    #[test]
    fn every_tool_the_server_answers_to_is_advertised() {
        // Every module that answers to a name of its own. `mod.rs` is not one
        // of them: it delegates to these and dispatches nothing itself, so
        // scanning it only ever matched this test's own `match name {` literal
        // and read the rest of the file as if it were dispatch.
        //
        // `constitution_packs` is not one either: it carries the policy-pack
        // definitions and helpers, but every one of those names is dispatched
        // from `constitution`, which is scanned. Listing it here would assert
        // it holds dispatch arms it does not have.
        const SOURCES: [(&str, &str); 11] = [
            ("amendments", include_str!("amendments.rs")),
            ("conformance", include_str!("conformance.rs")),
            ("constitution", include_str!("constitution.rs")),
            ("controls", include_str!("controls.rs")),
            ("design", include_str!("design/mod.rs")),
            ("evidence", include_str!("evidence.rs")),
            // `dispatch`'s `match name {` block, the only thing this scan
            // looks for, stays in the top-level module file; the other
            // executive submodules hold handler bodies, not the dispatch arm.
            ("executive", include_str!("executive/mod.rs")),
            ("fleet", include_str!("fleet.rs")),
            ("knowledge", include_str!("knowledge.rs")),
            ("lifecycle", include_str!("lifecycle.rs")),
            ("waivers", include_str!("waivers.rs")),
        ];

        let advertised: Vec<String> = list()
            .iter()
            .filter_map(|tool| tool["name"].as_str().map(str::to_string))
            .collect();

        let mut undeclared: Vec<String> = Vec::new();
        let mut dispatched = 0usize;

        for (module, source) in SOURCES {
            // Only the tool dispatch itself. Scanning whole files also matches
            // `"ratchet" => ControlKind::Ratchet` and friends, which are enum
            // parsing, not tools — a guard that reports those trains people to
            // ignore it.
            let mut from = 0usize;
            let mut found = 0usize;
            while let Some(at) = source[from..].find("match name {") {
                let start = from + at + "match name {".len();
                let end = source[start..]
                    .find("_ => None,")
                    .map(|e| start + e)
                    .unwrap_or(source.len());
                let block = &source[start..end];
                from = end;

                // Only the arms of `match name` itself. A collapsed tool
                // matches again inside its arm — `match decision`, `match
                // step`, `match view` — and those arms are argument values,
                // not tool names. Reporting them would train people to ignore
                // this guard for the same reason `"ratchet"` would, so the
                // scan tracks brace depth and reads the outer level only.
                let mut depth = 0usize;
                let mut opened_at: Option<usize> = None;
                let mut escaped = false;

                for (index, byte) in block.bytes().enumerate() {
                    match opened_at {
                        Some(open) => {
                            if escaped {
                                escaped = false;
                            } else if byte == b'\\' {
                                escaped = true;
                            } else if byte == b'"' {
                                opened_at = None;
                                if depth > 0 || !block[index..].starts_with("\" => ") {
                                    continue;
                                }
                                let name = &block[open + 1..index];
                                if name.is_empty() {
                                    continue;
                                }
                                found += 1;
                                if !advertised.iter().any(|a| a == name) {
                                    undeclared.push(format!("{module}::{name}"));
                                }
                            }
                        }
                        None => match byte {
                            b'"' => opened_at = Some(index),
                            b'{' => depth += 1,
                            b'}' => depth = depth.saturating_sub(1),
                            _ => {}
                        },
                    }
                }
            }

            // Per module, not just in total. The depth rule above is the kind
            // of narrowing that can stop reading a module altogether without
            // failing anything, which is the silence this test exists to break.
            assert!(
                found > 0,
                "the scan found no dispatch arms in {module}, so it is no longer \
                 reading the dispatch it claims to guard"
            );
            dispatched += found;
        }

        // A source scan that matches nothing passes silently, which is the
        // failure this test exists to catch, one level up.
        assert!(
            dispatched >= 40,
            "the scan found only {dispatched} dispatch arms, so it is no longer \
             reading the dispatch it claims to guard"
        );

        undeclared.sort();
        undeclared.dedup();
        assert!(
            undeclared.is_empty(),
            "the server answers to these but advertises none of them:\n  {}",
            undeclared.join("\n  ")
        );
    }

    #[test]
    fn tool_contract_requires_evidence_and_exposes_binding_mode() {
        let tools = list();
        let complete = tools
            .iter()
            .find(|tool| tool["name"] == "task_transition")
            .unwrap();
        // Evidence is not in `required`, because only `to="complete"` needs it;
        // the conditional requirement is enforced in dispatch and stated in the
        // schema, which is what a collapsed transition costs and repays.
        assert!(complete["inputSchema"]["properties"]["evidence"].is_object());
        assert!(complete["inputSchema"]["required"]
            .as_array()
            .unwrap()
            .iter()
            .any(|value| value == "to"));
        let link = tools
            .iter()
            .find(|tool| tool["name"] == "link_goal_to_artifact")
            .unwrap();
        assert_eq!(
            link["inputSchema"]["properties"]["mode"]["default"],
            "governed"
        );
        let create = tools
            .iter()
            .find(|tool| tool["name"] == "task_create")
            .unwrap();
        assert!(create["inputSchema"]["properties"]["blocked_by"].is_object());
    }

    /// Regression: `constitution_define` advertised `records` as a bare
    /// `{"type": "array"}` with no `items`. Strict MCP clients validate the
    /// advertised schema before they will load a server, so that one omission
    /// rejected the whole Lodestar tool surface with "tool parameters array
    /// type must have items" — every tool became uncallable, not just the one
    /// with the defect. The fix declares the structured record shape; this test
    /// holds the rule for every array in every advertised schema, because the
    /// next omission would be just as total and just as easy to miss.
    #[test]
    fn every_advertised_array_schema_declares_its_items() {
        fn walk(schema: &Value, path: &str, failures: &mut Vec<String>) {
            match schema {
                Value::Object(fields) => {
                    if fields.get("type").is_some_and(|ty| ty == "array")
                        && !fields.contains_key("items")
                    {
                        failures.push(path.to_string());
                    }
                    for (key, value) in fields {
                        walk(value, &format!("{path}.{key}"), failures);
                    }
                }
                Value::Array(entries) => {
                    for (index, value) in entries.iter().enumerate() {
                        walk(value, &format!("{path}[{index}]"), failures);
                    }
                }
                _ => {}
            }
        }

        let mut failures = Vec::new();
        for tool in list() {
            let name = tool["name"].as_str().unwrap_or("<unnamed>").to_string();
            walk(&tool["inputSchema"], &name, &mut failures);
        }

        assert!(
            failures.is_empty(),
            "array schema without `items` rejects the whole server: {failures:?}"
        );
    }

    #[test]
    fn tools_list_exposes_no_duplicate_names() {
        // Regression: ADR-0022 copy-pasted the `consolidate` definition, so
        // tools/list advertised two identical entries and MCP clients saw an
        // ambiguous, duplicated verb. Every advertised tool name must be unique.
        let tools = list();
        let mut names: Vec<&str> = tools
            .iter()
            .map(|tool| tool["name"].as_str().unwrap())
            .collect();
        let total = names.len();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), total, "duplicate tool name in tools/list");

        for tool in tools.iter().filter(|tool| {
            tool["inputSchema"]["properties"]["session_id"].is_object()
                && tool["name"] != "open_session"
        }) {
            assert!(tool["inputSchema"]["properties"]["agent"].is_null());
            // A tool may declare `session_id` without requiring anything at all
            // (`check_overlap` offers one to sharpen its answer), so an absent
            // `required` list is a legitimate shape here, not a missing key. It
            // trivially satisfies the rule this loop exists to enforce: the
            // caller is never asked for `agent`.
            let required = tool["inputSchema"]["required"]
                .as_array()
                .map(Vec::as_slice)
                .unwrap_or_default();
            assert!(!required.iter().any(|value| value == "agent"));
        }
    }

    /// ADR-0059 rule 2: the default profile is under 40 tools and under 6,000
    /// tokens. Measured the same way `scripts/measure-tool-surface.mjs` does —
    /// the compact JSON of the advertised array, tokens as bytes/4 — so the test
    /// and the benchmark cannot disagree about whether the bar is met.
    ///
    /// The second assertion is ADR-0093's headroom bound, not the ADR-0059
    /// ceiling repeated: a profile sitting at 5,976 of 6,000 tokens had no
    /// room for the next legitimate schema addition, which is exactly what
    /// happened (`gaps.d/lodestar-default-profile-token-budget-saturated.md`).
    /// This fails on the addition that *would* saturate the budget, not only
    /// on the one that finally breaches it — the margin is a decision this
    /// test enforces rather than one a PR discovers by hitting the wall.
    #[test]
    fn the_default_profile_is_under_budget() {
        let advertised = advertised_for(Profile::Default);
        assert!(
            advertised.len() < 40,
            "default profile advertises {} tools, the budget is under 40",
            advertised.len()
        );
        let bytes = serde_json::to_string(&advertised).unwrap().len();
        let tokens = bytes / 4;
        assert!(
            tokens < 6_000,
            "default profile is ~{tokens} tokens ({bytes}B), the ADR-0059 ceiling is under 6,000"
        );
        assert!(
            tokens < 5_500,
            "default profile is ~{tokens} tokens ({bytes}B), the ADR-0093 headroom bound is under \
             5,500 — some prior trim's margin has been spent; either trim narrative back out of a \
             description (ADR-0093) or make a deliberate decision to spend the headroom, not both \
             by accident"
        );
    }

